ref_dict.thm intro main:
\begin{theorem}\cite[Theorem 1.1, Remark 1.2]{BHS}
\label{thm intro main}
If $G$ is an algebraic group over a perfect field $k$, then $\pi_0^{\#A^1}(G)$ is a strongly $\#A^1$-invariant sheaf. Consequently, for any Nisnevich locally
trivial $G$-torsor $\@P \to \@X$ in $\@H(k)$,
\[
P \to X \to BG
\]
is an $\#A^1$-fiber sequence.
\end{theorem}

ref_dict.conj:GEM:
\begin{conjecture}[Generalised Euclid--Mullin conjecture]
\label{conj:GEM}
Let $a,m\in\N$ with $a^2\equiv1\pmod{m}$. Then
\begin{itemize}
\item[(i)] there exists $f\in\GEM(a,m)$ such that $\GEM_1(f;a,m)$ contains
every prime $p\equiv a\pmod{m}$;
\item[(ii)] for any $f\in\GEM(a,m)$, $\GEM_2(f;a,m)$ omits infinitely many
primes $p\equiv a\pmod{m}$.
\end{itemize}
\end{conjecture}

ref_dict.thm:firstprime:
