ref_dict.cor:centerpreservingprojirrep2:
\begin{cor}[of \Cref{thm:faithfulcenterpreservingirrep}] \label{cor:centerpreservingprojirrep2}
Let $H \leq G$, and suppose that $H$ possesses a faithful irreducible representation $\rho$. 
Let $c \in \rH^2(G,\muF)$ be such that $\restr{c}{H} = 1$. 
Then there exists an irreducible $c$-projective representation $\ol{\sigma}$ of $G$ such that $\ker(\ol{\sigma}) \cap H \leq \rZ_c(G)$ and $\restr{\ol{\sigma}}{H}$ contains the projectivization of $\rho$. 

If in addition $\rZ_c(G) \cap H = \{\ee\}$, then $\ol{\sigma}$ is an irreducible $c$-projective representation of $G$ which is faithful on $H$. 
\end{cor}

ref_dict.thm:faithfulcenterpreservingirrep:
\begin{thm} \label{thm:faithfulcenterpreservingirrep}
Let $H \leq G$ be finite groups. 
Suppose that $H$ has a faithful irreducible representation $\rho$. 
Then one of the irreducible constituents of $\ind_H^G(\rho)$ is center-preserving on $H$. 
\end{thm}

ref_dict.cor:centerpreserving:
\begin{cor}[{of \Cref{thm:Gaschutz}}] \label{cor:centerpreserving}
The following conditions are equivalent. 
\begin{enumerate}[leftmargin=2em,itemsep=.4ex,label=\textup{(\roman*)}]
    \item $G$ possesses an irreducible representation $\sigma$ with $\rZ(\sigma) = \rZ(G)$. 
    \item There exists a character $\chi \in \widehat{\rZ(G)}$ such that:
    \begin{enumerate}[label=(\arabic*)]
        \item \label{item:centerpreserving1} $\omega_\chi \colon \, \rZ_2(G)/\rZ(G) \to \widehat{G/[G,G]}$ is injective, and 
        \item \label{item:centerpreserving2} $\SocA(G/\ker(\chi))$ is generated by a single conjugacy class. 
\end{enumerate}
\end{enumerate}   
If in addition $G$ is nilpotent, then those conditions are equivalent to:
\begin{enumerate}[resume*]
\item There exists a character $\chi \in \widehat{\rZ(G)}$ such that $\omega_\chi $ is injective.
\end{enumerate}
\end{cor}

