Theorem \ref{T1} will be a consequence of Theorem \ref{T2A} and Theorem
\ref{T2B}.\ Moreover, by a theorem of Ramanujam \cite{r} which states that any
non-singular complex algebraic surface of contractible and simply connected at
infinity must be isomorphic to the affine two-space as algebraic variety.
Then, as a consquence of Theorem \ref{T1} and Theorem \ref{T2A}, one can
confirm the CR Yau uniformization conjecture with the maximal volume growth
condition for $n=2$.

By using the standard method as in the paper of Shi \cite{s1}, we have the
short-tome solution of the Sasaki-Ricci flow in a complete noncompact Sasakian
$(2n+1)$-manifold with bounded transverse holomorphic bisectional curvature.
However, by applying the so-called Sasaki-Chern-Ricci flow (\ref{1}) which is
the Sasaki analogue of Chern-Ricci flow as in recent papers of Lee-Tam
(\cite{lt2}), Tosatti-Weinkove (\cite{tw}) and Lott-Zhang (\cite{lz}), we have
the Sasaki analogue of the short-time solution for Sasaki-Ricci flow\ by removing the boundedness oftransverse holomorphic bisectional curvature.

\begin{proposition}
\label{P1} Let $(M,\xi,\eta,g_{0},\Phi,\omega_{0})$ be a complete noncompact
Sasakian $(2n+1)$-manifold with transverse nonnegative holomorphic bisectional
curvature and $V_{\xi}(x,1)\geq v_{0}$ for some $v_{0}>0$ and all $x\in M$. Then

\begin{enumerate}
\item there exist $T_{0}(n,v_{0})>0,C_{0}(n,v_{0})>0$ such that a family of
Sasakian structures $(M,\xi(t),\eta(t),g(t),\Phi(t),\omega(t))$ satisfying the
Sasaki-Ricci flow
\begin{equation}\begin{array}
[c]{lll}\frac{d}{dt}g_{i\overline{j}}^{T}(x,t) & = & -R_{i\overline{j}}^{T}(x,t),\\
g_{i\overline{j}}^{T}(x,0) & = & g_{i\overline{j}}^{T}(x).
\end{array}
\label{2020C}\end{equation}
with
\begin{equation}\begin{array}
[c]{c}||Rm^{T}||^{2}(x,t)\leq\frac{C_{0}}{t},\text{ \textrm{on}\ }M\times
\lbrack0,T_{0}).
\end{array}
\label{AAA}\end{equation}

\item $g(t)$ has transverse nonnegative holomorphic bisectional curvature and
the maximal volume growth condition is preserving.

\item
\[\begin{array}
[c]{c}V_{\xi}(x,1)\geq\frac{1}{2}v_{0}\end{array}
\]
on $M\times\lbrack0,T_{0}).$
\end{enumerate}
\end{proposition}

For a completeness, we will give a proof as in the appendix.

First we will have the
long-time solution of (\ref{2020C}):

\begin{theorem}
\label{T1A}Let $(M,\xi,\eta,g,\Phi,\omega)$ be a complete noncompact Sasakian
$(2n+1)$-manifold with nonnegative transverse bisectional curvature. Suppose
that there exists a constant $C_{2}>0$ such that
\[\begin{array}
[c]{c}\frac{1}{\mathrm{Vol}(B_{\xi}(x,r))}\int_{B_{\xi}(x,r)}R^{T}\omega^{n}\wedge\eta\leq\frac{C_{2}}{(1+r)^{2}},\text{\ \textrm{for all} }r,\text{ }x\in
M.
\end{array}
\]
Then the Sasaki-Ricci flow has a long time solution $g(x,t)$ on $M\times
\lbrack0,\infty).$ Moreover, the following are true:

\begin{enumerate}
\item For any $t\geq0$, $g_{i\overline{j}}^{T}(x,t)$ is transverse K\"{a}hler
with nonnegative transverse bisectional curvature.

\item For any integer $m\geq0$, there is a constant $C_{1}$ such that\begin{equation}\begin{array}
[c]{c}||\nabla^{m}Rm^{T}||^{2}(x,t)\leq\frac{C_{1}}{t^{1+m}},\text{\ \textrm{for
all} }t>0,\text{ }x\in M.
\end{array}
\label{BBB}\end{equation}

\item If in addition $(M,\eta,\Phi,g_{i\overline{j}}^{T}(x))$ has maximal
volume growth, then there exists a positive constant $C_{2}$ depending only on
the initial metric such that the injectivity radius of $g_{i\overline{j}
}(x,t)$ is bounded below by $C_{2}t^{\frac{1}{2}}$ for all $t\geq1$.
\end{enumerate}
\end{theorem}

\begin{theorem}
\label{T2A}Let $(M,\xi,\eta,g,\Phi,\omega)$ be a complete noncompact Sasakian
$(2n+1)$-manifold with nonnegative transverse bisectional curvature. Suppose
that for some positive constants $C_{1},C_{2}$, we have the maximal volume
growth\[\begin{array}
[c]{c}\mathrm{Vol}(B_{\xi}(p,r))\geq C_{1}r^{2n},\text{ \ \textrm{for all} }r\text{
\textrm{and some }}p\in M
\end{array}
\]
and
\[\begin{array}
[c]{c}\frac{1}{\mathrm{Vol}(B_{\xi}(x,r))}\int_{B_{\xi}(x,r)}R^{T}\omega^{n}\wedge\eta\leq\frac{C_{2}}{(1+r)^{2}},\text{\textrm{ for all} }r,x\in M.
\end{array}
\]
Then

\begin{enumerate}
\item $M$ is CR-biholomorphic to $\Omega\times\mathbb{R},$ where $\Omega$ is a
pseuodoconvex domain in the $\mathbb{C}^{n}$.

\item $M$ is homeomorphic to $\mathbb{R}^{4}\times\mathbb{R}$ for $n=2$ and
$M$ is diffeomorphic to $\mathbb{R}^{2n}\times\mathbb{R}$ for $n>2.$
\end{enumerate}
\end{theorem}

Next we show that

\begin{theorem}
\label{T2B}Let $(M,J,\theta)$ be a complete noncompact Sasakian $(2n+1)$-manifold with nonnegative transverse bisectional curvature and the maximal
volume growth. Then we have
\[\begin{array}
[c]{c}\frac{1}{B_{\xi}(x,r)}\int_{B_{\xi}(x,r)}R^{T}\omega^{n}\wedge\eta\leq\frac
{C}{1+r^{2}}\end{array}
\]
for all $r$, $x\in M$ and a positive constant $C$.
\end{theorem}

Then Theorem \ref{T1} will be a consequence of Theorem \ref{T2A} and Theorem
\ref{T2B}.

The paper is organized as follows. In section $2$, we review some preliminary
notions in a Sasakian manifold. In section $3,$ we show the Li-Yau-Hamilton
estimates and the Harnack inequalities for the Sasaki-Ricci flow (\ref{2020C}
). In section $4,$ we get the
long-time solution existence of the Sasaki-Ricci flow
(\ref{2020C})
. Then we prove the Yau's uniformization conjecture for a complete noncompact
Sasakian $(2n+1)$-manifold with nonnegative transverse bisectional curvature
in section $5$. In the appendix, we give a sketch proof of the Proposition
\ref{P1}.

