	 \leq \liminf_{j\to\infty} E_j[\boldsymbol u^{(j)}, \alpha^{(j)}].
\end{align*}

\item[ii)] {(\, $\Gamma$-$\limsup$ inequality)}

Given any $(\boldsymbol u,\alpha)\in \mathcal{S}$, it is possible to construct a sequence $(\boldsymbol{u}^{(j)},\alpha^{(j)})$ in $\mathcal{A}$ such that
 $$ \big (u_3^{(j)}, \alpha^{(j)}\big) \quad \text{converges strongly in } L^{2}(\Omega)\times L^2(\Omega)
 \text{ to } \big (u_3, \alpha\big ), $$
    and
    \[
    \lim_{j \to \infty} E_j[{\boldsymbol u}^{(j)}, \alpha^{(j)}] =\int_0^1 a_\eta\big(\alpha(z)\big) \cdot  \frac{1}{2} E u_3'(z)^2 + w\big(\alpha(z)\big) + \frac{w_1 \ell^2}{2L^2} |\alpha'(z)|^2  \, \mathrm{d}z.
    \]
\end{enumerate}

